1115						   int iface_no,
1116						   bool *has_non_pcm, bool non_pcm)
1117	{
1118		struct usb_device *dev;
1119		struct usb_interface *iface;
1120		struct usb_host_interface *alts;
1121		struct usb_interface_descriptor *altsd;
1122		int i, altno, err, stream;
1123		struct audioformat *fp = NULL;
1124		struct snd_usb_power_domain *pd = NULL;
1125		bool set_iface_first;
