1127	
1128		dev = chip->dev;
1129	
1130		/* parse the interface's altsettings */
1131		iface = usb_ifnum_to_if(dev, iface_no);
1132	
1133		num = iface->num_altsetting;
1134	
1135		/*
1136		 * Dallas DS4201 workaround: It presents 5 altsettings, but the last
1137		 * one misses syncpipe, and does not produce any sound.
1138		 */
1139		if (chip->usb_id == USB_ID(0x04fa, 0x4201) && num >= 4)
1140			num = 4;
1141	
1142		for (i = 0; i < num; i++) {
1143			alts = &iface->altsetting[i];
1144			altsd = get_iface_desc(alts);
1145			protocol = altsd->bInterfaceProtocol;
1146			/* skip invalid one */
1147			if (((altsd->bInterfaceClass != USB_CLASS_AUDIO ||
1148			      (altsd->bInterfaceSubClass != USB_SUBCLASS_AUDIOSTREAMING &&
1149			       altsd->bInterfaceSubClass != USB_SUBCLASS_VENDOR_SPEC)) &&
1150			     altsd->bInterfaceClass != USB_CLASS_VENDOR_SPEC) ||
1151			    altsd->bNumEndpoints < 1 ||
1152			    le16_to_cpu(get_endpoint(alts, 0)->wMaxPacketSize) == 0)
1153				continue;
1154			/* must be isochronous */
1155			if ((get_endpoint(alts, 0)->bmAttributes & USB_ENDPOINT_XFERTYPE_MASK) !=
1156			    USB_ENDPOINT_XFER_ISOC)
1157				continue;
1158			/* check direction */
1159			stream = (get_endpoint(alts, 0)->bEndpointAddress & USB_DIR_IN) ?
1160				SNDRV_PCM_STREAM_CAPTURE : SNDRV_PCM_STREAM_PLAYBACK;
1161			altno = altsd->bAlternateSetting;
1162	
1163			if (snd_usb_apply_interface_quirk(chip, iface_no, altno))
1164				continue;
1165	
1166			/*
1167			 * Roland audio streaming interfaces are marked with protocols
1168			 * 0/1/2, but are UAC 1 compatible.
1169			 */
1170			if (USB_ID_VENDOR(chip->usb_id) == 0x0582 &&
1171			    altsd->bInterfaceClass == USB_CLASS_VENDOR_SPEC &&
1172			    protocol <= 2)
1173				protocol = UAC_VERSION_1;
1174	
1175			switch (protocol) {
1176			default:
1177				dev_dbg(&dev->dev, "%u:%d: unknown interface protocol %#02x, assuming v1\n",
1178					iface_no, altno, protocol);
1179				protocol = UAC_VERSION_1;
1180				fallthrough;
1181			case UAC_VERSION_1:
1182			case UAC_VERSION_2: {
1183				int bm_quirk = 0;
1184	
1185				/*
1186				 * Blue Microphones workaround: The last altsetting is
1187				 * identical with the previous one, except for a larger
1188				 * packet size, but is actually a mislabeled two-channel
1189				 * setting; ignore it.
1190				 *
1191				 * Part 1: prepare quirk flag
1192				 */
1193				if (altno == 2 && num == 3 &&
1194				    fp && fp->altsetting == 1 && fp->channels == 1 &&
1195				    fp->formats == SNDRV_PCM_FMTBIT_S16_LE &&
1196				    protocol == UAC_VERSION_1 &&
1197				    le16_to_cpu(get_endpoint(alts, 0)->wMaxPacketSize) ==
1198								fp->maxpacksize * 2)
1199					bm_quirk = 1;
1200	
1201				fp = snd_usb_get_audioformat_uac12(chip, alts, protocol,
1202								   iface_no, i, altno,
1203								   stream, bm_quirk);
1204				break;
1205			}
1206			case UAC_VERSION_3:
1207				fp = snd_usb_get_audioformat_uac3(chip, alts, &pd,
1208							iface_no, i, altno, stream);
1209				break;
1210			}
1211	
1212			if (!fp)
1213				continue;
1214			else if (IS_ERR(fp))
