2127			    intfd->bAlternateSetting);
2128		usb_set_interface(umidi->dev, intfd->bInterfaceNumber,
2129				  intfd->bAlternateSetting);
2130	
2131		umidi->roland_load_ctl = snd_ctl_new1(&roland_load_ctl, umidi);
